pub fn is_balanced(s: Str) -> Bool {
  var stack: List[Str] = []
  for c in s.chars() {
    if c == "(" or c == "[" or c == "{" {
      stack = stack.push(c)
    } else if c == ")" or c == "]" or c == "}" {
      let expected = match c {
        ")" => "(",
        "]" => "[",
        _ => "{",
      }
      match stack.last() {
        None => { return false },
        Some(top) => {
          if top != expected {
            return false
          }
          stack = stack.remove_at(stack.len() - 1)
        },
      }
    }
  }
  return stack.is_empty()
}
